/**
 * P2-03 (ADR-011 §e): the runtime branch's gate policy payload builder. The
 * policy file content was read and shape-validated at startup by the host
 * channel; the dispatcher supplies its checked core per call and this
 * pure projection generates an adjudication row per observed FINDING and, for
 * ADR-022 version 2, a disposition row for every ACCEPTED finding. The row
 * identity travels the envelope axis alone (ruling 15,
 * ADR-006 §1.6: the read-back payload carries no identity echo), the row
 * structure is the ruling-14 corrective form (the finding_id parameter key,
 * sequential requirement keys over the file's prefix), and the host-owned
 * strings come from the validated template. An empty observation yields an
 * empty row array, which the gate derivation face refuses with the existing
 * incomplete-basis code.
 */
export function resolveHostGatePolicy(
  contract: HostReadinessPolicyContract,
  core: CanonicalStateCore,
): HostGatePolicyPayload {
  const findingRefs: { ref: string; accepted: boolean }[] = [];
  for (const envelope of core.objects) {
    const payload: unknown = envelope.payload;
    if (
      payload !== null &&
      typeof payload === 'object' &&
      !Array.isArray(payload) &&
      (payload as Record<string, unknown>)['kind'] === 'FINDING'
    ) {
      findingRefs.push({
        ref: String(envelope.ref),
        accepted: (payload as Record<string, unknown>)['adjudication_state'] === 'ACCEPTED',
      });
    }
  }
  const template = contract.requirement_row_template;
  const version = contract.finding_policy_version;
  const disposition = contract.disposition_row_template;
  if ((version === 2 || version === 3) && disposition === undefined) {
    throw new DomainError('READINESS_BASIS_INCOMPLETE', 'finding policy version 2 requires a disposition template');
  }
  const row = (rowTemplate: HostFindingRequirementTemplate, findingRef: string, index: number) => ({
    requirement_key: `${rowTemplate.requirement_key_prefix}${String(index + 1)}`,
    source: rowTemplate.source,
    resolver: rowTemplate.resolver,
    parameters: { finding_id: findingRef, ...(version === undefined ? {} : { finding_policy_version: version }) },
    enforcement: rowTemplate.enforcement,
    exception_policy: rowTemplate.exception_policy,
  });
  const rows = findingRefs.flatMap((finding, index) => [
    row(template, finding.ref, index),
    ...((version === 2 || version === 3) && disposition !== undefined && finding.accepted
      ? [row(disposition, finding.ref, index)]
      : []),
  ]);
  if (new Set(rows.map((requirement) => requirement.requirement_key)).size !== rows.length) {
    throw new DomainError('READINESS_POLICY_CONFLICT', 'finding requirement keys must be distinct');
  }
  return {
    policy: contract.policy,
    available_policies: contract.available_policies,
    requirement_rows: rows,
  };
}
